#!/usr/bin/env bash
# GSZ step129 — post-delivery instructions on WhatsApp. Per-product instructions
# field; on delivery a 2nd WhatsApp message (~4s after the credentials) sends the
# product's instructions. enqueue() gains an optional delay. Safe + idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step129-$TS"; TMP=$(mktemp -d)
FILES=(lib/wanotify.js routes/checkout.js routes/adminCatalog.js views/admin/product_edit.ejs)
echo "==> step129: post-delivery WhatsApp instructions"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$TMP/m.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; for f in lib/wanotify.js routes/checkout.js routes/adminCatalog.js; do node --check "$GSZ/$f"; done
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/admin/product_edit.ejs','utf8'),{filename:'$GSZ/views/admin/product_edit.ejs'});console.log('    ejs ok')"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step129 OK ✅  Add 'Post-delivery instructions' to any product in its editor. On delivery, the customer gets a 2nd WhatsApp message (~4s after the account details) with those instructions."
